void dfs(int u, const std::vector<std::vector<int>>& adj, std::vector<bool>& visited, std::vector<int>& comp) {
    visited[u] = true;
    comp.push_back(u);
    for (int v : adj[u]) {
        if (!visited[v]) {
            dfs(v, adj, visited, comp);
        }
    }
}

int main() {
    int n = 0;
    int m = 0;
    std::cin >> n >> m;
    std::vector<std::vector<int>> adj(n);
    for (int i = 0; i < m; ++i) {
        int u = 0;
        int v = 0;
        std::cin >> u >> v;
        adj[u].push_back(v);
        adj[v].push_back(u);
    }
    for (auto& neighbors : adj) {
        std::sort(neighbors.begin(), neighbors.end());
    }

    std::cout << "degrees:";
    for (const auto& neighbors : adj) {
        std::cout << ' ' << neighbors.size();
    }
    std::cout << '\n';

    std::vector<bool> visited(n, false);
    std::vector<std::vector<int>> components;
    for (int start = 0; start < n; ++start) {
        if (!visited[start]) {
            std::vector<int> comp;
            dfs(start, adj, visited, comp);
            std::sort(comp.begin(), comp.end());
            components.push_back(std::move(comp));
        }
    }

    std::cout << "components: " << components.size() << '\n';
    for (const auto& comp : components) {
        for (std::size_t i = 0; i < comp.size(); ++i) {
            if (i > 0) {
                std::cout << ' ';
            }
            std::cout << comp[i];
        }
        std::cout << '\n';
