```

```cpp
std::vector<int> dist(n, -1);
std::vector<int> parent(n, -1);
std::queue<int> q;
dist[src] = 0;
q.push(src);
while (!q.empty()) {
    int u = q.front();
    q.pop();
    for (int v : adj[u]) {
        if (dist[v] == -1) {
            dist[v] = dist[u] + 1;
            parent[v] = u;
            q.push(v);
        }
    }
}
```

Set `dist` and `parent` when you push, not when you pop. Each node then enters the queue once and keeps the parent that found it first. A node still at -1 after the loop is unreachable, so check `dist[target]` before you build a path.

To rebuild the path, walk `parent` back from the target until you hit -1, then `std::reverse` the result. When several shortest paths tie, sorted adjacency lists plus parent-on-first-discovery give the *lexicographically smallest* one: the path with the smaller node at the first place they differ. Unsorted lists still give a shortest path, just not a predictable one.

example.code:
#include <algorithm>
#include <iostream>
#include <queue>
#include <vector>

int main() {
    int n = 0;
    int m = 0;
    std::cin >> n >> m;
    std::vector<std::vector<int>> adj(n);
    for (int i = 0; i < m; ++i) {
        int u = 0;
        int v = 0;
        std::cin >> u >> v;
        adj[u].push_back(v);
        adj[v].push_back(u);
    }
    for (auto& neighbors : adj) {
        std::sort(neighbors.begin(), neighbors.end());
    }

    const int src = 0;
    const int target = n - 1;
    std::vector<int> dist(n, -1);
    std::vector<int> parent(n, -1);
    std::queue<int> q;
    dist[src] = 0;
    q.push(src);
    while (!q.empty()) {
        int u = q.front();
        q.pop();
        for (int v : adj[u]) {
            if (dist[v] == -1) {
                dist[v] = dist[u] + 1;
                parent[v] = u;
                q.push(v);
            }
        }
    }

    std::vector<int> path;
    for (int v = target; v != -1; v = parent[v]) {
        path.push_back(v);
    }
    std::reverse(path.begin(), path.end());
    std::cout << "distance: " << dist[target] << '\n';
    std::cout << "path:";
    for (int v : path) {
        std::cout << ' ' << v;
    }
    std::cout << '\n';
    return 0;
}

