    std::vector<int> indeg(n, 0);
    for (int i = 0; i < m; ++i) {
        int a = 0;
        int b = 0;
        std::cin >> a >> b;
        adj[a].push_back(b);
        ++indeg[b];
    }

    std::priority_queue<int, std::vector<int>, std::greater<int>> ready;
    for (int u = 0; u < n; ++u) {
        if (indeg[u] == 0) {
            ready.push(u);
        }
    }
    std::vector<int> order;
    while (!ready.empty()) {
        int u = ready.top();
        ready.pop();
        order.push_back(u);
        for (int v : adj[u]) {
            --indeg[v];
            if (indeg[v] == 0) {
                ready.push(v);
            }
        }
    }

    if (static_cast<int>(order.size()) < n) {
        std::cout << "cycle" << '\n';
    } else {
        for (std::size_t i = 0; i < order.size(); ++i) {
